/**
 * Parses the arguments according to the specified options and properties.
 *
 * @param options the specified Options
 * @param properties command line option name-value pairs
 * @param nonOptionAction see {@link NonOptionAction}.
 * @param arguments the command line arguments
 *
 * @return the list of atomic option and value tokens.
 * @throws ParseException if there are any problems encountered while parsing the command line tokens.
 * @since 1.10.0
 */
public CommandLine parse(final Options options, final Properties properties, final NonOptionAction nonOptionAction, final String... arguments) throws ParseException {
    this.options = Objects.requireNonNull(options, "options");
    this.nonOptionAction = nonOptionAction;
    skipParsing = false;
    currentOption = null;
    expectedOpts = new ArrayList<>(options.getRequiredOptions());
    // clear the data from the groups
    for (final OptionGroup optionGroup : options.getOptionGroups()) {
        optionGroup.setSelected(null);
    }
    cmd = CommandLine.builder().setDeprecatedHandler(deprecatedHandler).get();
    if (arguments != null) {
        for (final String argument : arguments) {
            handleToken(argument);
        }
    }
    // check the arguments of the last option
    checkRequiredArgs();
    // add the default options
    handleProperties(properties);
    checkRequiredOptions();
    return cmd;
}
